// Load reads and validates a catalog from disk.
func Load(path string) (*Catalog, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read content %q: %w", path, err)
	}
	var catalog Catalog
	if err := json.Unmarshal(b, &catalog); err != nil {
		return nil, fmt.Errorf("decode content %q: %w", path, err)
	}
	if err := catalog.Validate(); err != nil {
		return nil, fmt.Errorf("invalid content %q: %w", path, err)
	}
	return &catalog, nil
}

// Validate catches authoring mistakes at startup instead of during a run.
func (c *Catalog) Validate() error {
	if c == nil {
		return errors.New("catalog is nil")
	}
	if c.FailureScene.Title == "" || !strings.HasPrefix(c.FailureScene.Background, "res://assets/") || len(c.FailureScene.Dialogue) == 0 {
		return errors.New("failure scene requires title, asset background and dialogue")
	}
	for _, line := range c.FailureScene.Dialogue {
		if strings.TrimSpace(line.Speaker) == "" || strings.TrimSpace(line.Text) == "" {
			return errors.New("empty failure dialogue")
		}
	}
	for _, reason := range []string{"erosion_limit", "puzzle_attempt_limit", "battle_requirements_not_met", "session_expired"} {
		line := c.FailureScene.FirstLines[reason]
		if strings.TrimSpace(line.Speaker) == "" || strings.TrimSpace(line.Text) == "" {
			return fmt.Errorf("missing failure first line: %s", reason)
		}
	}
	if c.Version != CurrentVersion {
		return fmt.Errorf("content version must be %d", CurrentVersion)
	}
	if c.GameID == "" {
		return errors.New("game_id is required")
	}
	if len(c.Chapters) == 0 {
		return errors.New("at least one chapter is required")
	}
	if _, ok := c.Skills["挥墨"]; !ok {
		return errors.New("basic attack skill 挥墨 is required")
	}
	for name, skill := range c.Skills {
		if name == "" || skill.Description == "" || skill.CooldownMS <= 0 || skill.Damage < 0 || skill.Shield < 0 || skill.Heal < 0 {
			return fmt.Errorf("invalid skill %q", name)
		}
	}
	for ci := range c.Chapters {
		for ei := range c.Chapters[ci].Events {
			event := &c.Chapters[ci].Events[ei]
			if !event.Draft {
				art, ok := c.Art[event.ID]
				if !ok || art.BackdropColor == "" || art.WhisperAudio == "" {
					return fmt.Errorf("playable event %q missing backdrop or whisper audio", event.ID)
				}
			}
			memory, ok := c.Memories[event.Reward.MemoryID]
			if !ok {
				return fmt.Errorf("event %q references missing memory %q", event.ID, event.Reward.MemoryID)
			}
			if memory.ID != event.Reward.MemoryID || memory.Source != c.Chapters[ci].ID+"/"+event.ID {
				return fmt.Errorf("memory %q source does not match event", memory.ID)
			}
			if memory.Title == "" || memory.Summary == "" || memory.RememberedText == "" || memory.ForgottenText == "" {
				return fmt.Errorf("memory %q missing narrative text", memory.ID)
			}
			if len(event.Story.Beats) == 0 || event.Story.Outro == "" || len(event.Story.Dialogue) == 0 || len(event.Story.Clues) != len(event.Investigations) {
				return fmt.Errorf("event %q missing story", event.ID)
			}
			for _, line := range event.Story.Dialogue {
				if line.Speaker == "" || line.Text == "" {
					return fmt.Errorf("event %q has empty dialogue", event.ID)
				}
			}
			if !strings.HasPrefix(memory.Image, "res://assets/rubbings/") || !strings.HasSuffix(memory.Image, ".png") {
				return fmt.Errorf("memory %q needs a packaged rubbing image", memory.ID)
			}
			if _, ok := c.Skills[memory.Skill]; memory.Skill != "" && !ok {
				return fmt.Errorf("memory %q references missing skill %q", memory.ID, memory.Skill)
			}
			if memory.EchoAudio == "" {
				return fmt.Errorf("memory %q missing echo audio", memory.ID)
			}
			event.Reward.Memory = memory
		}
	}
	chapterIDs := make(map[string]struct{}, len(c.Chapters))
	for _, chapter := range c.Chapters {
		if chapter.ID == "" || chapter.Title == "" {
			return errors.New("chapter id and title are required")
		}
		if _, exists := chapterIDs[chapter.ID]; exists {
			return fmt.Errorf("duplicate chapter id %q", chapter.ID)
		}
		chapterIDs[chapter.ID] = struct{}{}
		if chapter.UnlockCost < 0 {
			return fmt.Errorf("chapter %q has negative unlock cost", chapter.ID)
		}
		eventIDs := make(map[string]struct{}, len(chapter.Events))
		for _, event := range chapter.Events {
			if event.ID == "" || event.Title == "" {
				return fmt.Errorf("chapter %q has event without id/title", chapter.ID)
			}
			if _, exists := eventIDs[event.ID]; exists {
				return fmt.Errorf("chapter %q has duplicate event id %q", chapter.ID, event.ID)
			}
	var style := StyleBoxFlat.new()
	style.bg_color = Color("#29423f")
	style.border_color = Color("#688477")
	style.set_border_width_all(1)
	style.set_corner_radius_all(8)
	style.content_margin_left = 12
	style.content_margin_right = 12
	style.content_margin_top = 10
	style.content_margin_bottom = 10
	button.add_theme_stylebox_override("normal", style)
	var hover := style.duplicate()
	hover.bg_color = Color("#3d5b51")
	button.add_theme_stylebox_override("hover", hover)
	var pressed := style.duplicate()
	pressed.bg_color = Color("#596447")
	button.add_theme_stylebox_override("pressed", pressed)
	var disabled := style.duplicate()
	disabled.bg_color = Color("#223236")
	disabled.border_color = Color("#344c46")
	button.add_theme_stylebox_override("disabled", disabled)
	button.add_theme_color_override("font_disabled_color", Color("#acb8b3"))
	button.add_theme_font_size_override("font_size", 18)
	button.pressed.connect(func():
		if not busy:
			soundscape.cue("ui")
			callback.call())
	parent.add_child(button)
	return button

# Finished rubbing art is a packaged bitmap, never generated at runtime.
func _memory_art(parent: Node, id: String, height: float) -> TextureRect:
	var memory := data.memory(id)
	var title := str(memory.get("title", id))
	var path := data.memory_image_path(id)
	if path.is_empty():
		_label(parent, title + " · 拓印图待装裱", 18, Color("#b7c0b8"))
		return null
	var texture := load(path) as Texture2D
	if texture == null:
		_label(parent, title + " · 拓印图待装裱", 18, Color("#b7c0b8"))
		return null
	var art := _art_banner(parent, texture, height)
	art.stretch_mode = TextureRect.STRETCH_KEEP_ASPECT_CENTERED
	return art

func _task_event() -> Dictionary:
	for chapter in data.catalog.chapters:
		for event in chapter.events:
			if not event.draft and not GameState.player.completed_events.has(chapter.id + ":" + event.id):
				return {"chapter": chapter.id, "event": event}
	return {}

func _add_current_task(parent: Node) -> void:
	var task := _task_event()
	if task.is_empty():
		_label(parent, "全篇已完成 · 檐下的故事仍在继续", 23, Color("#e4c98a"))
		_label(parent, "你留下了 %d 段记忆、%d 条抉择。可以在剧情册回看旅程。" % [GameState.player.memories.size(), GameState.player.memory_ledger.size()], 18)
		return
	_label(parent, "当前任务 · " + str(task.event.title), 23, Color("#e4c98a"))
	for objective in task.event.objectives: _label(parent, "· " + str(objective), 17)
	if session_id.is_empty():
		_button(parent, "前往任务", _open_event.bind(task.chapter, task.event.id))
	else:
		_button(parent, "继续当前修复", _resume)

func _close_dialogue() -> void:
	if is_instance_valid(dialogue_stage):
		dialogue_stage.dismiss()
	dialogue_stage = null

func _begin_dialogue(title: String, lines: Array, done: Callable, back: Callable, mode: String = "story", key: String = "") -> void:
	_close_dialogue()
	dialogue_title = title
	dialogue_key = key if not key.is_empty() else title
	dialogue_mode = mode
	dialogue_lines = lines
	dialogue_done = done
	dialogue_return = back
	dialogue_index = clampi(int(story_progress.get_value("dialogue", dialogue_key, 0)), 0, maxi(0, lines.size() - 1))
	_render_dialogue()

func _render_dialogue() -> void:
	flow = "gameover" if dialogue_mode == "failure" else "dialogue"
	if not is_instance_valid(dialogue_stage):
		_clear()
		dialogue_stage = preload("res://scripts/dialogue_stage.gd").new()
		dialogue_stage.failure = dialogue_mode == "failure"
		dialogue_stage.backdrop = load(str(data.catalog.failure_scene.background)) if dialogue_mode == "failure" else _event_background()
		add_child(dialogue_stage)
		dialogue_stage.advance_requested.connect(_advance_dialogue)
		dialogue_stage.previous_requested.connect(_previous_dialogue)
		dialogue_stage.skip_requested.connect(_finish_dialogue)
		dialogue_stage.back_requested.connect(func(): dialogue_return.call())
	dialogue_stage.show_line(dialogue_title, dialogue_lines[dialogue_index], dialogue_index, dialogue_lines.size(), bool(story_progress.get_value("read",dialogue_key,false)))

func _previous_dialogue() -> void:
	if dialogue_index == 0: return
	dialogue_index -= 1
	_save_dialogue_cursor()
	_render_dialogue()

func _save_dialogue_cursor() -> void:
	story_progress.set_value("dialogue", dialogue_key, dialogue_index)
	var error := story_progress.save("user://story-" + str(GameState.player.id) + ".cfg")
	if error != OK: status.text = "剧情阅读位置未能保存；游戏进度不受影响。"

func _advance_dialogue() -> void:
	if busy or not is_instance_valid(dialogue_stage): return
	if dialogue_index + 1 >= dialogue_lines.size():
		_finish_dialogue()
		return
	dialogue_index += 1
	_save_dialogue_cursor()
	_render_dialogue()

func _finish_dialogue() -> void:
	# Failure recovery is revealed only after the ninth line; there is no skip control.
	if dialogue_mode == "failure" and dialogue_index + 1 < dialogue_lines.size(): return
	story_progress.set_value("read", dialogue_key, true)
	dialogue_index = 0
	_save_dialogue_cursor()
	_close_dialogue()
	dialogue_done.call()

func _begin_failure() -> void:
	failure_key = "failure:" + session_id + ":" + str(GameState.session.retries)
	if bool(story_progress.get_value("read",failure_key,false)):
		_show_failure_actions()
		return
	var scene: Dictionary = data.catalog.failure_scene
	var lines: Array = scene.dialogue.duplicate(true)
	var reason := str(GameState.session.failure_reason)
	if scene.first_lines.has(reason): lines[0] = scene.first_lines[reason].duplicate(true)
	_begin_dialogue(scene.title,lines,_show_failure_actions,Callable(),"failure",failure_key)

func _show_failure_actions() -> void:
	flow = "failed"
	_clear()
	_art_banner(page,load(str(data.catalog.failure_scene.background)),240)
	_label(page,"飞鸟山 · 墨迹未尽",26,Color("#e4c98a"))
	var reasons := {"erosion_limit":"侵蚀已达 100", "puzzle_attempt_limit":"修复尝试用尽", "session_expired":"旧版本事件已超时", "battle_requirements_not_met":"白蚀未清除或未施展所需技能"}
	var response: Dictionary = GameState.session
	_label(page,"事件失败：%s。已拓印记忆仍保留。" % reasons.get(response.failure_reason,response.failure_reason),19)
	_label(page,"解谜 %d/%d · 已清除白蚀 %d 波" % [int(response.puzzle_score),int(response.puzzle_total),int(response.battle_waves)],18)
	_label(page,"回溯会恢复本次事件开始时的侵蚀与谜题；已拓印记忆、技艺和已确认的取舍保留。墨痕为零时免费回溯。",19)
extends Control

signal dodge_triggered

var hp := 30
var max_hp := 30
var shield := 0
var hits := 0
var phase := 0.0
var effect := 0.0
var effect_color := Color.WHITE
var effect_text := ""
var defeated := false
var background: Texture2D
var active := false
var player_position := Vector2(0.50, 0.78)
var enemy_position := Vector2(0.50, 0.28)
var joystick := Vector2.ZERO
var dragging_stick := false
var dodge_armed := false
var motion_time := 0.0

func _ready() -> void:
	custom_minimum_size = Vector2(0, 250)
	mouse_filter = Control.MOUSE_FILTER_STOP

func flash(text: String, color: Color) -> void:
	effect_text = text
	effect_color = color
	effect = 0.7

func _process(delta: float) -> void:
	motion_time += delta
	if active and not defeated:
		var direction := Input.get_vector("move_left", "move_right", "move_up", "move_down") + joystick
		if direction.length() > 0:
			player_position += Vector2(direction.x, direction.y * 0.72).limit_length() * delta * 0.52
			player_position = player_position.clamp(Vector2(0.08, 0.38), Vector2(0.92, 0.90))
			if phase > 0.68 and not dodge_armed:
				dodge_armed = true
				dodge_triggered.emit()
		var chase_target := Vector2(player_position.x + sin(motion_time * 1.7) * 0.10, maxf(0.20, player_position.y - 0.34))
		enemy_position = enemy_position.move_toward(chase_target, delta * 0.13)
		enemy_position = enemy_position.clamp(Vector2(0.14, 0.18), Vector2(0.86, 0.56))
		if phase < 0.32: dodge_armed = false
	effect = maxf(0, effect - delta)
	queue_redraw()

func _gui_input(event: InputEvent) -> void:
	var stick_center := Vector2(52, size.y - 54)
	if event is InputEventMouseButton and event.button_index == MOUSE_BUTTON_LEFT:
		if event.pressed and event.position.distance_to(stick_center) < 42:
			dragging_stick = true
			joystick = ((event.position - stick_center) / 32.0).limit_length()
