				}
			}
		}
	}
	for _, chapter := range c.Chapters {
		if chapter.NextChapter != "" {
			if _, exists := chapterIDs[chapter.NextChapter]; !exists {
				return fmt.Errorf("chapter %q points to missing next chapter %q", chapter.ID, chapter.NextChapter)
			}
		}
	}
	return nil
}

